/* Game rules are kept independent of rendering. */
(function(root){'use strict';
class RunState {
  constructor(random=Math.random){this.random=random;this.reset();}
  reset(){this.mode='ready';this.lane=0;this.x=0;this.y=0;this.vy=0;this.slide=0;this.distance=0;this.coins=0;this.elapsed=0;this.speed=14;this.rawScore=0;this.powers={magnet:0,shield:0,double:0};this.invulnerable=0;this.revives=2;this.milestones=[];this.items=[];this.nextRow=65;this.id=0;this.rows=0;this.cause='';this.events=[];}
  get score(){return Math.floor(this.rawScore);}
  start(){this.reset();this.mode='running';for(let n=0;n<7;n++)this.add('coin',0,-12-n*2.5);this.add('barrier',0,-45);this.add('train',1,-81);this.add('shield',-1,-57,1.1);for(let n=0;n<6;n++)this.add('coin',-1,-34-n*2.5);this.add('gate',-1,-100);this.add('magnet',0,-112,1.1);}
  action(action){if(this.mode!=='running')return false;if(action==='left')this.lane=Math.max(-1,this.lane-1);else if(action==='right')this.lane=Math.min(1,this.lane+1);else if(action==='jump' && this.y===0){this.slide=0;this.vy=9.5;}else if(action==='slide'){this.slide=.85; if(this.y>0)this.vy=-13;}else return false;return true;}
  revive(){if(!['ended','crashed'].includes(this.mode)||this.revives<=0)return false;this.revives--;this.mode='reviving';this.y=0;this.vy=0;this.slide=0;this.invulnerable=3;this.items=this.items.filter(i=>!(['train','barrier','gate'].includes(i.type)&&i.z>-20&&i.z<16));return true;}
  step(dt){this.events=[];if(this.mode!=='running')return;dt=Math.min(Math.max(dt,0),.05);this.elapsed+=dt;for(const key of Object.keys(this.powers))this.powers[key]=Math.max(0,this.powers[key]-dt);this.invulnerable=Math.max(0,this.invulnerable-dt);this.speed=Math.min(27,14+this.distance/140);const move=this.speed*dt;this.distance+=move;this.rawScore+=move*3*(this.powers.double>0?2:1);this.x+=(this.lane*2.6-this.x)*(1-Math.exp(-18*dt));if(this.vy || this.y>0){this.vy-=21*dt;this.y=Math.max(0,this.y+this.vy*dt);if(this.y===0)this.vy=0;}this.slide=Math.max(0,this.slide-dt);this.nextRow-=move;if(this.nextRow<=0){this.spawnRow();this.nextRow+=Math.max(24,36-this.distance/150);}
    for(const item of this.items){const old=item.z;item.z+=move;if(item.taken)continue;const nearX=Math.abs(this.x-item.lane*2.6)<(item.type==='coin'?.78:1.12);if(item.type==='coin'){const magnet=this.powers.magnet>0 && item.z>-13 && item.z<2;if(magnet || (nearX && old<1.2 && item.z>=-1.2 && Math.abs((this.y+.95)-item.height)<1.05)){item.taken=true;this.coins++;this.rawScore+=25*(this.powers.double>0?2:1);this.events.push({type:'coin',item,magnet});}continue;}
      if(['magnet','shield','double'].includes(item.type)){if(nearX && old<1.2 && item.z>=-1.2 && Math.abs(this.y+1-item.height)<1.3){item.taken=true;this.powers[item.type]=Math.max(this.powers[item.type],{magnet:9,shield:14,double:10}[item.type]);this.events.push({type:'power',item});}continue;}
      if(!nearX || this.invulnerable>0)continue;const half=item.type==='train'?4.5:.48;if(old < half+.34 && item.z>=-half-.34){if(item.type==='barrier' && this.y>1.1)continue;if(item.type==='gate' && this.slide>0 && this.y<.3)continue;if(this.powers.shield>0){this.powers.shield=0;this.invulnerable=1.2;this.events.push({type:'shield-hit',item});continue;}
        this.mode='ended';this.cause=item.type;this.events.push({type:'crash',item});break;}}
    this.items=this.items.filter(i=>i.z<16&&!i.taken);const crash=this.events.find(e=>e.type==='crash');if(crash)this.events=this.events.filter(e=>e!==crash);for(const score of [300,800,1500,3000,5000]){if(this.score<score||this.milestones.includes(score))continue;this.milestones.push(score);if(score===300)this.powers.shield=Math.max(this.powers.shield,9);if(score===800)this.powers.magnet=Math.max(this.powers.magnet,10);if(score===1500)this.powers.double=Math.max(this.powers.double,10);if(score===3000){this.revives++;this.powers.shield=Math.max(this.powers.shield,14);}if(score===5000){this.powers.magnet=12;this.powers.double=12;this.powers.shield=14;}this.events.push({type:'milestone',score});}if(crash)this.events.push(crash);
  }
  add(type,lane,z,height=.95){const item={id:++this.id,type,lane,z,height,taken:false};this.items.push(item);return item;}
  spawnRow(){this.rows++;const choose=()=>Math.floor(this.random()*3)-1;const lane=choose();const r=this.random();const type=r<.4?'train':r<.73?'barrier':'gate';this.add(type,lane,-92);if(this.distance>180 && this.random()<.42){let other=choose();if(other===lane)other=lane===1?0:lane+1;this.add(this.random()<.55?'barrier':'gate',other,-92);}const safe=[-1,0,1].filter(l=>!this.items.some(i=>['train','gate','barrier'].includes(i.type)&&i.lane===l&&Math.abs(i.z+92)<12));const coinLane=safe[Math.floor(this.random()*safe.length)];for(let n=0;n<7;n++)this.add('coin',coinLane,-79-n*2.5);if(this.rows%3===1){const type=['magnet','shield','double'][Math.floor(this.random()*3)];this.add(type,coinLane,-101,1.1);}}
}
root.RunState=RunState;if(typeof module!=='undefined')module.exports={RunState};
})(typeof globalThis!=='undefined'?globalThis:this);
